func RedeemCoupon(ctx context.Context, db *sql.DB, couponID string) error {
	var remaining int
	db.QueryRowContext(ctx, "SELECT remaining_uses FROM coupons WHERE id=$1", couponID).Scan(&remaining)
	if remaining <= 0 {
		return errors.New("coupon exhausted")
	}
	_, err := db.ExecContext(ctx, "UPDATE coupons SET remaining_uses = remaining_uses - 1 WHERE id=$1", couponID)
